    private Gate3PlayerFacingTextSmokeSuite() { }

    @FunctionalInterface
    private interface SmokeCase { void run() throws Exception; }

    /** Named timing and exact last-started-case reporting for the bounded CI run. */
    private static void runSmoke(String name, SmokeCase smoke) throws Exception {
        System.out.println("[GATE3] BEGIN " + name);
        System.out.flush();
        long started = System.nanoTime();
        try {
            smoke.run();
        } catch (Exception | Error failure) {
            System.err.println("[GATE3] FAILED " + name + ": " + failure);
            throw failure;
        } finally {
            System.out.println("[GATE3] END " + name + " elapsedMs="
                    + ((System.nanoTime() - started) / 1_000_000L));
            System.out.flush();
        }
    }
